  "Your cart, your language, your sign-in session and these privacy choices.": "ጋሪዎ፣ ቋንቋዎ፣ የመግቢያ ክፍለ ጊዜዎ እና እነዚህ የግላዊነት ምርጫዎች።",
  "Currency, sounds, recent searches, starred parts and your devices.": "ምንዛሬ፣ ድምጾች፣ የቅርብ ፍለጋዎች፣ ኮከብ ያደረጓቸው ክፍሎች እና መሣሪያዎችዎ።",
  "Which pages are opened and how fast they load. Never your name or contact.": "የትኞቹ ገጾች እንደሚከፈቱ እና ምን ያህል በፍጥነት እንደሚጫኑ። ስምዎን ወይም አድራሻዎን ፈጽሞ አይደለም።",
  "The kinds of parts you look at, to show matching offers.": "የሚመለከቷቸው የክፍል አይነቶች፣ ተዛማጅ ቅናሾችን ለማሳየት።",
  "Until you clear them (sign-in: until you sign out).": "እስኪያጸዱ ድረስ (መግቢያ፦ እስኪወጡ ድረስ)።",
  "12 months, or until you clear them.": "12 ወራት፣ ወይም እስኪያጸዱ ድረስ።",
