  "6 months.": "6 ወራት።",
  "Without them the cart would empty and the site would forget your language on every page.": "ያለ እነሱ ጋሪው ባዶ ይሆናል፣ ጣቢያውም በእያንዳንዱ ገጽ ቋንቋዎን ይረሳል።",
  "So you do not have to set things up again on every visit.": "በእያንዳንዱ ጉብኝት ሁሉንም እንደገና ማቀናበር አያስፈልግዎትም።",
  "To see which pages are slow or confusing and fix them.": "የትኞቹ ገጾች ቀርፋፋ ወይም ግራ የሚያጋቡ እንደሆኑ አይተን እናስተካክላቸዋለን።",
  "So the offers you see are for your phones, not random ones.": "ቅናሾች በዘፈቀደ ሳይሆን ለስልኮችዎ እንዲሆኑ።",
  "You add a screen to the cart, open another page, and it is still there.": "ስክሪን ወደ ጋሪ ይጨምራሉ፣ ሌላ ገጽ ይከፍታሉ፣ አሁንም እዚያ አለ።",
  "You searched \"A54 battery\" yesterday; today it is first in your recent searches.": "ትናንት \"A54 battery\" ፈልገዋል፤ ዛሬ በቅርብ ፍለጋዎች ላይ የመጀመሪያው ነው።",
  "We notice the Repair page loads slowly on phones and make it faster.": "በስልኮች ላይ የጥገና ገጹ ቀስ ብሎ እንደሚጫን አይተን እናፋጥነዋለን።",
  "You look at iPhone 13 screens; the next deal we show you is for that screen.": "የiPhone 13 ስክሪኖችን ይመለከታሉ፤ ቀጣዩ ቅናሽ ለዚያ ስክሪን ነው።",
