  "Estimate": "ግምት",
  "Show this at the counter. The final price is confirmed after the free check.": "ይህን በቆጣሪው ያሳዩ። የመጨረሻው ዋጋ ከነጻ ምርመራ በኋላ ይረጋገጣል።",
  "Print": "አትም",
  "Bench now": "ጠረጴዛው አሁን",
  "TAP WHAT IS BROKEN": "የተሰበረውን ይንኩ",
  "Point at the part": "ወደ ክፍሉ ያመልክቱ",
  "Every layer of the phone opens its repair below, with every grade and the total.": "እያንዳንዱ የስልኩ ንብርብር ከታች ጥገናውን ይከፍታል፣ ከሁሉም ደረጃዎችና ድምሩ ጋር።",
