  "FROM FACTORY TO YOUR BENCH": "ከፋብሪካ እስከ ጠረጴዛዎ",
  "Every part has a journey.": "እያንዳንዱ ክፍል ጉዞ አለው።",
  "CREATE YOUR ACCOUNT": "መለያዎን ይክፈቱ",
  "MY BENCH · SIGN IN": "My Bench · ግባ",
  "Talk to a person": "ከሰው ጋር ይነጋገሩ",
  "Here is a photo of my phone. What does it need?": "ይህ የስልኬ ፎቶ ነው። ምን ያስፈልገዋል?",
  "Thanks for the photo! I can’t look at photos right now, so send it to the team on WhatsApp and they will tell you the part and the price.": "ለፎቶው እናመሰግናለን! አሁን ፎቶውን ማየት አልችልም፣ ስለዚህ በWhatsApp ለቡድኑ ይላኩ፣ ክፍሉን እና ዋጋውን ይነግሩዎታል።",
  "Thanks for the photo! Send it to the team on WhatsApp and they will tell you the part and the price.": "ለፎቶው እናመሰግናለን! በWhatsApp ለቡድኑ ይላኩ፣ ክፍሉን እና ዋጋውን ይነግሩዎታል።",
  "Where do I find my model code?": "የሞዴል ኮዴን የት አገኛለሁ?",
