  "New list name": "የአዲስ ዝርዝር ስም",
  "See my lists": "ዝርዝሮቼን ይመልከቱ",
  "Request it": "ጠይቅ",
  "Reviews open once we have confirmed your order of this part, so every review is a verified purchase.": "ለዚህ ክፍል ያለዎትን ትዕዛዝ ካረጋገጥን በኋላ አስተያየት ይከፈታል፣ ስለዚህ እያንዳንዱ አስተያየት የተረጋገጠ ግዢ ነው።",
  "Only customers who bought this part can review it, after we confirm their order.": "ይህን ክፍል የገዙ ደንበኞች ብቻ ትዕዛዛቸው ከተረጋገጠ በኋላ አስተያየት መስጠት ይችላሉ።",
  "Prices and stock shown are test data while the shop is set up": "ሱቁ እስኪዘጋጅ ድረስ ዋጋና ክምችት የሙከራ ዳታ ናቸው",
