  'I looked closely but couldn’t read a model on this photo. A screenshot of Settings → About phone works best, or just tell me the model.': 'በደንብ ተመለከትኩ ግን በዚህ ፎቶ ላይ ሞዴል ማንበብ አልቻልኩም። የሴቲንግ → ስለ ስልክ ስክሪንሾት ይሻላል፣ ወይም ሞዴሉን ብቻ ይንገሩኝ።',
