  'This part of the site is still being built. Everything you need is on the home page in the meantime.': 'ይህ የጣቢያው ክፍል ገና በመገንባት ላይ ነው። እስከዚያው የሚያስፈልግዎ ሁሉ በመነሻ ገጹ ላይ አለ።',
