  'Add your phone under My devices and the shop marks every part that fits. Not sure of your model? Use Find My Part, ask Samsoom, or send him a photo of Settings → About.': 'ስልክዎን በእኔ መሣሪያዎች ስር ያክሉ፤ ሱቁ የሚገጥመውን እያንዳንዱን ክፍል ምልክት ያደርጋል። ሞዴልዎን እርግጠኛ አይደሉም? Find My Part ይጠቀሙ፣ ሳምሱምን ይጠይቁ ወይም የቅንብሮች → ስለ ፎቶ ይላኩለት።',
