  'Tip: bring the phone with the battery above 20% so the team can test it straight away.': 'ምክር፦ ወዲያው እንዲፈተሽ ስልኩን ከ20% በላይ ባትሪ ይዘው ይምጡ።',
  'Tip: trade accounts see trade prices on every part once approved.': 'ምክር፦ የንግድ መለያዎች ከጸደቁ በኋላ በእያንዳንዱ ክፍል የንግድ ዋጋ ያያሉ።',
